import { style } from 'typestyle';

import LinkToRevision from './LinkToRevision';
import RevisionRow from './RevisionRow';
import TestHeader from './TestHeader';
import {
  RESULTS_TABLE_MIN_WIDTH,
  type compareView,
  type compareOverTimeView,
} from '../../common/constants';
import { Spacing } from '../../styles';
import type { CombinedResultsItemType } from '../../types/state';
import { TestVersion } from '../../types/types';
import { crossPlatformGroupKey } from '../../utils/subtestsLinks';

// We're using typestyle styles on purpose, to avoid the performance impact of
// MUI's sx prop for these numerous elements.
// Also note that we're using paddings, not margins. Indeed Virtuoso can't
// compute properly the heights of the elements if we're using margins, but
// paddings work fine.
const styles = {
  testBlock: style({
    /* Note that this padding will be added to the padding below */
    paddingTop: Spacing.Small,
    // Floor the row width to match the header, so columns can't compress into
    // each other; below this the page scrolls horizontally.
    minWidth: RESULTS_TABLE_MIN_WIDTH,
  }),
  revisionBlock: style({ paddingBottom: Spacing.Large }),
};

function TableRevisionContent(props: Props) {
  const {
    results,
    view,
    rowGridTemplateColumns,
    replicates,
    testVersion,
    expandAll,
    crossPlatformLinks,
  } = props;

  if (!results.length) {
    return null;
  }

  // All results are for the same test, so any result should generate the same
  // header appropriately.
  // Here we use the first result for the first revision.
  //                                         First result
  //                               Value of the tuple |
  //                                First revision |  |
  //                                            |  |  |
  //                                            v  v  v
  const representativeResultForHeader = results[0][1][0];
  const hasMoreThanOneNewRev = results.length > 1;

  // The cross-platform matrix compares one base revision against one new one,
  // so a group that holds several new revisions gets no link for now. The links
  // are computed by the table across header groups (see buildCrossPlatformLinks).
  const crossPlatformLink = hasMoreThanOneNewRev
    ? null
    : (crossPlatformLinks?.get(
        crossPlatformGroupKey(representativeResultForHeader),
      ) ?? null);

  return (
    <div
      className={`table-revision-content ${styles.testBlock}`}
      role='rowgroup'
    >
      <TestHeader
        result={representativeResultForHeader}
        withRevision={!hasMoreThanOneNewRev}
        crossPlatformLink={crossPlatformLink}
      />
      {results.map(([revision, listOfResults]) => (
        <div
          className={`revision-block ${styles.revisionBlock}`}
          key={revision}
        >
          {hasMoreThanOneNewRev && <LinkToRevision result={listOfResults[0]} />}
          {listOfResults.map((result) => (
            <RevisionRow
              key={result.platform}
              result={result}
              view={view}
              gridTemplateColumns={rowGridTemplateColumns}
              replicates={replicates}
              testVersion={testVersion}
              expandAll={expandAll}
            />
          ))}
        </div>
      ))}
    </div>
  );
}

interface Props {
  // "results" contains all results for just one test, grouped by revisions.
  //
  //              revision        list of results for one test and revision
  //                 |               |
  //                 v               v
  results: Array<[string, CombinedResultsItemType[]]>;
  rowGridTemplateColumns: string;
  view: typeof compareView | typeof compareOverTimeView;
  replicates: boolean;
  testVersion: TestVersion;
  expandAll: boolean;
  // Cross-platform subtests links keyed by crossPlatformGroupKey; absent for
  // the over-time view.
  crossPlatformLinks?: Map<string, string>;
}

export default TableRevisionContent;
